/* ==========================================================================
   12. 下状态栏（#EBF1F8 冰白图标内胆 + #080830 午夜蓝发送圆钮 + 透明底无顶线 + 方圆角打字框）
   ==========================================================================
   【下状态栏整体与各部件调节总指南】：
   1. 整体上下移动（贴底或抬高）：
      - 修改 `.input-row-wrapper` 的 `padding: 9px 12px 11px 12px`：
        第1个值 `9px` 是顶部留白，第3个值 `11px` 是底部留白（把 `11px` 改大如 `22px`，整排输入栏就会往上抬高；改小如 `4px` 就会往下贴底）。
   2. 整体左右边距：
      - 修改 `.input-row-wrapper` 的第2、4个值 `12px`（改大则左右往中间缩，改小则往屏幕两边撑开）。
   3. 中间打字框宽度与高度：
      - 高度：同时修改 `.input-action-bar-custom`、`.input-box-custom` 和 `.input-action-bar-custom:not(:focus-within)::before` 的 `height: 36px` 与 `line-height: 36px`。
      - 宽度：打字框是自动伸缩的（`flex: 1`），它的右侧留白由 `.input-action-bar-custom` 的 `margin-right: 78px` 控制（改小则打字框变宽，改大则打字框变窄）。
   ========================================================================== */

/* 12.1 底部输入区外层容器（全透明无边框） */
.chat-detail-screen .input-area-custom {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border-top: none !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 0 !important;
}

/* 12.2 输入栏单行主容器（控制整排上下高度与左右边距） */
.chat-detail-screen .input-row-wrapper {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  gap: 8px !important;                    /* 【调节】左头像、打字框、发送键之间的水平间距 */
  padding: 9px 12px 11px 12px !important; /* 【调节】上9px、右12px、下11px（改大下边距可把整栏往上推）、左12px */
  box-sizing: border-box !important;
  width: 100% !important;
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border-top: none !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 右侧按钮组平铺 */
.chat-detail-screen .input-btns-right {
  display: contents !important;
}

/* 12.3 左侧加号按钮 (.input-btn-plus)：34×34px 虚线圆框我方头像 + 右下角 #080830 午夜蓝底小加号 */
.chat-detail-screen .input-btn-plus {
  position: relative !important;
  flex: 0 0 34px !important;              /* 【调节】左侧我方头像按钮宽度（需与 width 同步改） */
  width: 34px !important;                 /* 【调节】左侧我方头像按钮宽度 */
  height: 34px !important;                /* 【调节】左侧我方头像按钮高度 */
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;                   /* 【调节】如需单独微调上下左右，可写如 margin: -2px 0 0 4px */
}

.chat-detail-screen .input-btn-plus > svg {
  display: none !important;
}

.chat-detail-screen .input-btn-plus::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  border-radius: 50% !important;
  background-color: #EBF1F8 !important;
  background-image: var(--user-avatar) !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: cover !important;
  border: 1.2px dashed #080830 !important;
  box-shadow: 0 0 0 1px #98B0D0 !important;
  pointer-events: none !important;
}

.chat-detail-screen .input-btn-plus::after {
  content: '+' !important;
  position: absolute !important;
  inset: auto !important;
  right: -2px !important;                 /* 【调节】头像右下角小加号的左右偏移 */
  bottom: -1px !important;                /* 【调节】头像右下角小加号的上下偏移 */
  width: 12px !important;                 /* 【调节】小加号圆圈宽度 */
  height: 12px !important;                /* 【调节】小加号圆圈高度 */
  border-radius: 50% !important;
  background: #080830 !important;
  color: #FFFFFF !important;
  border: 1.2px solid #FFFFFF !important;
  font-size: 9px !important;
  font-weight: 900 !important;
  line-height: 9.5px !important;
  text-align: center !important;
  pointer-events: none !important;
}

/* 12.4 中间打字框容器 (.input-action-bar-custom)：内部全透明 + 方圆角 7px */
.chat-detail-screen .input-action-bar-custom {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  display: flex !important;
  align-items: center !important;
  background: transparent !important;
  background-color: transparent !important;
  border: 1.2px solid #080830 !important;
  border-radius: 7px !important;          /* 【调节】打字框圆角：7px 为方圆角（5px 更方，999px 为椭圆胶囊） */
  box-shadow: none !important;
  padding: 0 10px 0 12px !important;      /* 【调节】打字框内部左右内边距：右10px、左12px */
  height: 36px !important;                /* 【调节】打字框整体高度 */
  box-sizing: border-box !important;
  position: relative !important;
  overflow: visible !important;
  margin-right: 78px !important;          /* 【调节】打字框右侧预留给「麦克风+AI按钮」的宽度（改大打字框变短，改小打字框变长） */
}

/* 12.5 输入框文字本体 (.input-box-custom) */
.chat-detail-screen .input-box-custom {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  resize: none !important;
  font-size: 13.5px !important;           /* 【调节】打字输入文字字号大小 */
  font-weight: 500 !important;
  color: #080830 !important;
  caret-color: #405880 !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 36px !important;           /* 【调节】与打字框 height 保持一致，确保单行文字垂直居中 */
  height: 36px !important;                /* 【调节】与打字框 height 保持一致 */
  overflow-y: auto !important;
  scrollbar-width: none !important;
}

.chat-detail-screen .input-box-custom::-webkit-scrollbar {
  display: none !important;
}

.chat-detail-screen .input-box-custom::placeholder,
.chat-detail-screen .input-box-custom::-webkit-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

/* 12.6 输入框占位提示文字（读取顶部 --input-placeholder-text 变量，默认 'Message...'） */
.chat-detail-screen .input-action-bar-custom:not(:focus-within)::before {
  content: var(--input-placeholder-text) !important;
  position: absolute !important;
  left: 12px !important;                  /* 【调节】占位文字距离打字框左边框的距离 */
  top: 0 !important;                      /* 【调节】占位文字上下偏移 */
  height: 36px !important;
  line-height: 36px !important;
  font-size: 13.5px !important;           /* 【调节】占位文字字号大小 */
  color: #405880 !important;
  font-weight: 500 !important;
  pointer-events: none !important;
  white-space: nowrap !important;
  z-index: 1 !important;
}

.chat-detail-screen .input-action-bar-custom:focus-within::before,
.chat-detail-screen .input-action-bar-custom:has(textarea:not(:placeholder-shown))::before {
  display: none !important;
}

/* 12.7 右侧第 1 个大图标：表情贴纸按钮（.input-btn-sticker，#EBF1F8 冰白内胆 + #080830 线条） */
.chat-detail-screen .input-btn-sticker {
  position: relative !important;
  flex-shrink: 0 !important;
  width: 28px !important;                 /* 【调节】贴纸按钮点击区宽度 */
  height: 28px !important;                /* 【调节】贴纸按钮点击区高度 */
  min-width: 28px !important;
  opacity: 1 !important;
  pointer-events: auto !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 -4px 0 0 !important;          /* 【调节】贴纸按钮在打字框右端的位置（改 -4px 可左右微调） */
