.chat-detail-screen .send-btn-custom,
.chat-detail-screen .stop-btn-custom {
  position: relative !important;
  flex: 0 0 34px !important;              /* 【调节】发送按钮宽高尺寸（需同步修改下方 width/height/min/max） */
