/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ 黑白灰 · CSS 顶栏 · 7799 */
/* 修改这里的状态文字即可。 */
.chat-detail-screen {
  --sb-header-status: "▶︎ •၊၊||၊|။||||။ෆ";
  /* 更换横幅时，替换引号里的图片 URL。 */
  --sb-banner-art: url("https://img.baibai.cv/f/BW5bTX/IMG_7328.jpeg");
  --sb-header-safe-top: env(safe-area-inset-top, 0px);
  --sb-banner-top: calc(var(--sb-header-safe-top) + 6px);
  --sb-banner-inset: max(10px, calc((100% - 420px) / 2));
  --sb-banner-card-height: calc(clamp(108px, 31vw, 128px) - 4px + var(--sb-banner-inner-inset));
  --sb-banner-row: 49px;
  --sb-banner-card-gap: 5px;
  --sb-header-name-offset: 9px;
  --sb-header-name-size: 14px;
  --sb-header-name-line: 18px;
  --sb-header-status-offset: calc(var(--sb-header-name-offset) + var(--sb-header-name-line));
  --sb-header-status-line: 13px;
  --sb-header-text-edge: 2px;
  --sb-banner-avatar: 31px;
  --sb-banner-avatar-top: calc(var(--sb-banner-top) + (var(--sb-banner-row) - var(--sb-banner-avatar)) / 2);
  --sb-banner-inner-inset: 9px;
  --sb-banner-avatar-start: calc(var(--sb-banner-inset) + var(--sb-banner-inner-inset));
  --sb-banner-back-hit: 44px;
  --sb-banner-name-start: calc(var(--sb-banner-avatar-start) + var(--sb-banner-avatar) + 9px);
}

/* 黑白灰 · 微信聊天美化
   聊天气泡样式选「素淨」。
   素材已内嵌。--sb-text-size 和 --plain-content-max-width 可微调字号、长文宽度。 */
.chat-detail-screen {
  --mic-btn-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23646464%22%20stroke-width%3D%221.9%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Crect%20x%3D%229%22%20y%3D%223%22%20width%3D%226%22%20height%3D%2212%22%20rx%3D%223%22%2F%3E%3Cpath%20d%3D%22M5.5%2011.5V13a6.5%206.5%200%200%200%2013%200v-1.5M12%2019.5V22%22%2F%3E%3C%2Fsvg%3E");
  --sticker-btn-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23151515%22%20stroke-width%3D%221.9%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M8%203.5h8a4.5%204.5%200%200%201%204.5%204.5v5l-7.5%207.5H8A4.5%204.5%200%200%201%203.5%2016V8A4.5%204.5%200%200%201%208%203.5Z%22%2F%3E%3Cpath%20d%3D%22M13%2020.5V17a4%204%200%200%201%204-4h3.5%22%2F%3E%3C%2Fsvg%3E");
  --plus-btn-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23151515%22%20stroke-width%3D%221.9%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M12%204v16M4%2012h16%22%2F%3E%3C%2Fsvg%3E");

  --sb-text-size: 15px;
  --chat-header-bg: transparent;
  --chat-header-height: calc(var(--sb-banner-card-height) + var(--sb-banner-top) + 6px);
  --chat-header-blur: 0px;
  --chat-header-border: transparent;
  --chat-header-title-size: 16px;
  --chat-header-title-color: #171717;
  --chat-header-title-weight: 550;
  --chat-header-icon-color: #171717;
  --chat-header-unread-bg: transparent;
  --chat-header-unread-num-bg: #d9d9d9;
  --chat-header-unread-num-color: #171717;

  --chat-messages-padding: 12px 11px 22px;
  --chat-messages-gap: 3px;
  --plain-gap-between-groups: 15px;
  --plain-gap-within-group: 3px;
  --sb-connected-radius: 6px;
  --plain-content-max-width: 70%;
  --plain-padding-left-me: 25px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 25px;
  --plain-avatar-size: 33px;
  --plain-avatar-gap: 11px;
  --plain-avatar-radius: 50%;
  --avatar-size: 33px;
  --avatar-radius: 50%;
  --avatar-shadow: none;

  --sb-fill-me: #000;
  --sb-fill-them: #efefef;
  --bubble-me-bg: transparent;
  --bubble-them-bg: transparent;
  --bubble-me-bg-gradient: none;
  --bubble-them-bg-gradient: none;
  --bubble-me-color: #fff;
  --bubble-them-color: #111111;
  --bubble-me-font-size: var(--sb-text-size);
  --bubble-them-font-size: var(--sb-text-size);
  --bubble-me-line-height: 1.35;
  --bubble-them-line-height: 1.35;
  --bubble-me-border: none;
  --bubble-them-border: none;
  --bubble-me-shadow: none;
  --bubble-them-shadow: none;

  --timestamp-color: #777;
  --timestamp-size: 10px;
  --sb-time-after: 30px;
  --timestamp-margin: 7px auto var(--sb-time-after);
  --date-divider-bg: #f7f7f7;
  --date-divider-color: #777;
  --date-divider-size: 11px;
  --date-divider-weight: 400;
  --date-divider-radius: 4px;
  --date-divider-padding: 2px 6px;

  --sb-footer-send-icon: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23151515%22%20stroke-width%3D%221.9%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M7%204h10a4%204%200%200%201%204%204v7a4%204%200%200%201-4%204h-5l-5%203v-3a4%204%200%200%201-4-4V8a4%204%200%200%201%204-4Z%22%2F%3E%3Cpath%20d%3D%22M7.5%209h9M7.5%2013H13%22%2F%3E%3C%2Fsvg%3E");
  --input-area-bg: #fff;
  --input-area-padding: 6px 9px;
  --input-area-min-height: 48px;
  --input-area-border-top: 0;
  --input-area-blur: 0px;
  --input-box-bg: #efefef;
  --input-box-radius: 999px;
  --input-box-border: none;
  --input-box-shadow: none;
  --input-box-padding: 8px 10px;
  --input-box-font-size: 14px;
  --input-box-placeholder: transparent;
  --input-caret-color: #111111;
  --input-btn-color: #171717;
  --plus-btn-color: #171717;
  --plus-btn-bg: transparent;
  --plus-btn-size: 29px;
  --send-btn-color: #111111;
}

.chat-detail-screen .chat-header-custom {
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  height: var(--chat-header-height) !important;
  min-height: var(--chat-header-height) !important;
  flex-shrink: 0;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.chat-detail-screen.chat-detail-screen .chat-header-custom::before {
  content: var(--sb-header-status);
  position: absolute;
  z-index: 0;
  inset: var(--sb-banner-top) 50% auto var(--sb-banner-inset);
  height: calc(var(--sb-banner-row) - var(--sb-banner-card-gap));
  box-sizing: border-box;
  padding: var(--sb-header-status-offset) 4px 0 calc(var(--sb-banner-inner-inset) + var(--sb-banner-avatar) + 9px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #707070;
  font: 400 10px/var(--sb-header-status-line) system-ui, sans-serif;
  text-align: left;
  border-radius: 16px;
  background: #fff !important;
  pointer-events: none;
}
.chat-detail-screen.chat-detail-screen .chat-header-custom::after {
  content: "";
  position: absolute;
  z-index: 1;
  inset: calc(var(--sb-banner-top) + var(--sb-banner-row)) var(--sb-banner-inset) 6px;
  box-sizing: border-box;
  border: var(--sb-banner-inner-inset) solid transparent;
  border-radius: 18px;
  background:
    var(--sb-banner-art) center 46% / cover no-repeat padding-box,
    linear-gradient(#fff, #fff) border-box !important;
  pointer-events: none;
}
.chat-detail-screen .chat-header-custom :where(div, button, a):has(.header-avatar-container, .chat-header-title):not(.chat-header-title, .header-avatar-container, :has(.header-btn-back, .header-btn-info)) {
  position: static !important;
  transform: none !important;
}
.chat-detail-screen .chat-header-custom .header-avatar-container {
  position: absolute !important;
  z-index: 3;
  inset: var(--sb-banner-avatar-top) auto auto var(--sb-banner-avatar-start) !important;
  width: var(--sb-banner-avatar) !important;
  height: var(--sb-banner-avatar) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: none !important;
  opacity: 1 !important;
  border: 0 !important;
  border-radius: 50% !important;
  overflow: hidden !important;
  background-color: #dedede;
}
.chat-detail-screen .chat-header-custom .header-avatar-container :is(img, picture, .header-avatar, .header-avatar-img),
.chat-detail-screen .chat-header-custom .header-avatar-container > :is(div, span, button):has(img) {
