  font-size: 12px !important;
  line-height: 1.35 !important;
}
.chat-detail-screen .msg-reply-detached-me { align-self: flex-end !important; }
/* 对方的独立引用保持左对齐。 */
.chat-detail-screen .msg-reply-detached-them { align-self: flex-start !important; }
.chat-detail-screen .msg-reply-block-detached :is(.msg-reply-detached-name, .msg-reply-detached-text, .msg-reply-detached-media) {
